static const NSUInteger TFMaxText=512*1024,TFMaxEdits=24;
static NSDictionary *StringType(void){return @{@"type":@"string"};}
static NSDictionary *NumberType(void){return @{@"type":@"integer",@"minimum":@1};}
static NSDictionary *Schema(NSString *name,NSString *desc,NSDictionary *properties,NSArray *required){return @{@"name":name,@"description":desc,@"parameters":@{@"type":@"object",@"properties":properties,@"required":required,@"additionalProperties":@NO}};}
static BOOL Error(NSError **error,NSString *text){if(error)*error=TFAIToolError(text);return NO;}
static void Complete(TFAIResult callback,NSDictionary *result,NSError *error){dispatch_async(dispatch_get_main_queue(),^{if(callback)callback(result,error);});}
static NSString *ReadText(NSString *path,NSError **error){NSDictionary *attrs=[NSFileManager.defaultManager attributesOfItemAtPath:path error:error];if(!attrs)return nil;if([attrs[NSFileSize] unsignedLongLongValue]>TFMaxText){Error(error,@"文件超过 512 KB；请先选择较小文件或在编辑器拆分上下文");return nil;}NSData *data=[NSData dataWithContentsOfFile:path options:0 error:error];NSString *text=data?[[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding]:nil;if(data&&!text){Error(error,@"只读取 UTF-8 文本；二进制文件不作为代码发送");return nil;}if(TFAIContainsSecret(text)){Error(error,@"文件含疑似密钥，已停止读取；请移除敏感内容后重新选择");return nil;}return text;}
static NSDictionary *Immutable(NSDictionary *object){NSData *data=TFAIJSON(object,nil);return data?[NSJSONSerialization JSONObjectWithData:data options:0 error:nil]:nil;}
static BOOL IsWrite(NSString *name){return [@[@"prepare_project",@"clean_builds",@"apply_approved_patch",@"create_file",@"request_delete",@"build_project",@"cancel_build",@"git_save_version",@"git_download_updates",@"git_upload",@"download_file",@"extract_archive"] containsObject:name];}
static BOOL IsCritical(NSString *name){return [@[@"prepare_project",@"clean_builds",@"request_delete",@"git_save_version",@"git_download_updates",@"git_upload",@"download_file",@"extract_archive"] containsObject:name];}
