 for(NSURL *url in enumerator){if(self.cancelled){Error(error,@"操作已停止");return nil;}if(-start.timeIntervalSinceNow>8){Error(error,@"文件枚举超过 8 秒，请缩小目录");return nil;}NSString *enumerated=url.path.stringByStandardizingPath;NSString *urlBase=[NSURL fileURLWithPath:base].path.stringByStandardizingPath;NSString *relative=[enumerated substringFromIndex:urlBase.length+1];if(prefix.length)relative=[prefix stringByAppendingPathComponent:relative];NSNumber *dir=nil,*link=nil;[url getResourceValue:&dir forKey:NSURLIsDirectoryKey error:nil];[url getResourceValue:&link forKey:NSURLIsSymbolicLinkKey error:nil];if(link.boolValue||!TFAIAllowedRelativePath(relative)){if(dir.boolValue)[enumerator skipDescendants];continue;}if(!dir.boolValue){[paths addObject:relative];if(paths.count>=1001)break;}}
