 NSString *current=edit[@"after"],*needle=raw[@"before"],*replacement=raw[@"after"];NSRange range=[current rangeOfString:needle];if(range.location==NSNotFound||[current rangeOfString:needle options:0 range:NSMakeRange(NSMaxRange(range),current.length-NSMaxRange(range))].location!=NSNotFound){Error(error,@"原内容未找到或匹配不唯一，请读取文件并提供唯一上下文");return nil;}edit[@"after"]=[current stringByReplacingCharactersInRange:range withString:replacement];edit[@"line"]=@([[current substringToIndex:range.location] componentsSeparatedByString:@"\n"].count);if([edit[@"after"] lengthOfBytesUsingEncoding:NSUTF8StringEncoding]>TFMaxText||TFAIContainsSecret(edit[@"after"])){Error(error,@"修改后文件超过 512 KB 或含疑似密钥");return nil;}}
