}
- (void)undo:(TFAIResult)completion {
 dispatch_async(TMCGitService.queue,^{NSError *error=nil;TMCGitLease *lease __attribute__((objc_precise_lifetime))=[TMCGitLease acquire];if([TMCGitLease isBuilding:self.root]){Complete(completion,nil,TFAIToolError(@"构建进行中，请稍后撤回"));return;}
 NSDictionary *pointer=TFAIReadJSON([self.privateRoot stringByAppendingPathComponent:@"last-undo.json"]);NSString *backup=pointer[@"backup"];if(![backup isKindOfClass:NSString.class]||![backup hasPrefix:[[self.privateRoot stringByAppendingPathComponent:@"Backups"] stringByAppendingString:@"/"]]){Complete(completion,nil,TFAIToolError(@"本会话暂无可撤回的代码修改"));return;}
 NSMutableDictionary *transaction=[TFAIReadJSON(backup) mutableCopy];if(![transaction[@"state"] isEqual:@"applied"]){Complete(completion,nil,TFAIToolError(@"上次修改已经撤回或需要检查恢复记录"));return;}NSArray *edits=transaction[@"edits"];for(NSDictionary *edit in edits){NSString *full=TFAISafePath(self.root,edit[@"path"],NO,&error);if(!full||![TFAIDigest([NSData dataWithContentsOfFile:full]) isEqual:edit[@"afterHash"]]){Complete(completion,nil,error?:TFAIToolError(@"应用后文件已有人工修改，已停止撤回以保护新内容"));return;}}
 NSMutableArray *restored=[NSMutableArray new];for(NSDictionary *edit in edits){if(![self writeEdit:edit restore:YES error:&error])break;[restored addObject:edit];}
 if(restored.count!=edits.count){BOOL rolled=YES;for(NSDictionary *edit in [restored reverseObjectEnumerator])if(![self writeEdit:edit restore:NO error:nil])rolled=NO;if(!rolled)error=TFAIToolError(@"撤回中断且恢复未完成，请检查备份");Complete(completion,nil,error);return;}
 transaction[@"state"]=@"undone";if(!TFAIWriteJSON(transaction,backup,&error)){Complete(completion,@{@"status":@"undone",@"warning":@"文件已恢复，但备份状态保存失败"},error);return;}[self audit:@{} status:@"undone"];Complete(completion,@{@"status":@"undone",@"files":@([edits count]),@"message":@"已撤回上次 AI 代码修改；聊天记录保持不变"},nil);
 });
}
- (void)cancel {self.cancelled=YES;self.git.cancelled=YES;[self.downloader cancel];[self.extraction cancel];}
